import{_ as e,c as t,o,a4 as a}from"./chunks/framework.DzOtv0XR.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"project/bug.md","filePath":"project/bug.md"}'),l={name:"project/bug.md"},p=a('<h2 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to &quot;原则&quot;">​</a></h2><ul><li>上策：在用户感知反馈前解决，影响最小</li><li>中策： 随着时间，影响面扩大，被动处理</li></ul><p>事故通报优于事故处理</p><p>接收需求、UI 变化时，要求尽量小改动、增量式，减少不必要改动，影响隐藏逻辑</p><h2 id="开发、测试沟通协作" tabindex="-1">开发、测试沟通协作 <a class="header-anchor" href="#开发、测试沟通协作" aria-label="Permalink to &quot;开发、测试沟通协作&quot;">​</a></h2><ul><li>一般性 bug 走流程流转。如果是阻塞性 bug 可同时发群里</li><li>目的是提升协作效率，开发对一般性 bug 可以集中时间高效处理</li></ul><p><a href="https://zhuanlan.zhihu.com/p/136858266" target="_blank" rel="noreferrer">Bug的生命周期状态流程图 - 知乎</a></p><p>当你正在打造那些可能会失败的东西时，必须要接受一些无法避免的错误。人们不应该为聪明的失败承担责任，而应该为没有从中学到经验承担责任。——Ozan Varol</p><p>在这种环境下，那些仍然不愿意公开谈论失败的工程师，那些仍然对“总结经验教训”敷衍潦草的工程师，注定将一事无成。</p><p><strong>这些团队拥有开放的氛围，员工认为探讨错误的做法是安全的，他们更愿意与他人分享失败的经验，并积极努力减少失败，所以他们的表现更为优秀</strong>。</p><p>埃德蒙森把这种氛围称为心理安全。用埃德蒙森的话来说，<strong>心理安全是指“在实现雄心勃勃的绩效目标过程中，没有人会因为犯错、提问或求助而受到惩罚或羞辱”</strong>。</p><p>心理不安 的环境是指，犯错会被惩罚和羞辱。<strong>这种环境会形成恶性循环。那些表现最差、最需要改进的团队也最不可能上报错误</strong>；而如果错误没有上报，团队便无法改进。</p><blockquote><p>在日常工作中，对于事故处理，我们一向遵从航天二十字诀：定位准确、机理清楚、可以复现、措施有效、举一反三。</p></blockquote><blockquote><p>凡是被不断重复的过程，一定要将其工具化，绑定到自动化流程之中，减少基层员工不必要的心智负担</p></blockquote><blockquote><p>首先是我在最后时刻才寻求公司内部资源支持，所以我们遇到线上事故的时候，一定要拿起电话召集人马，不要拖延。</p></blockquote><blockquote><p>我通读了所有的系统知识库文章，经常会跑去看一看各种开源系统的 Feature List 和 Bugfix，看看它们发布了什么特性，修复了什么缺陷。</p></blockquote><h2 id="如何高效定位-bug" tabindex="-1">如何高效定位 bug <a class="header-anchor" href="#如何高效定位-bug" aria-label="Permalink to &quot;如何高效定位 bug&quot;">​</a></h2><p>定位 bug 是软件开发过程中的重要环节，下面是一些高效定位 bug 的方法：</p><ol><li><p>重现 bug：尽量多的了解 bug 的现象，并试图重现它。</p></li><li><p>查看日志：检查系统日志和应用程序日志，以了解 bug 的根源。</p></li><li><p>单步调试：使用调试器来单步执行代码，以更好地了解代码执行过程。</p></li><li><p>使用断点：在代码中设置断点，以便在程序执行到该点时停止并检查变量的值。</p></li><li><p>查看代码：仔细检查代码，以寻找可能导致 bug 的语法错误或逻辑错误。</p></li><li><p>使用测试：编写单元测试和集成测试，以便在每次更改代码后立即检测 bug。</p></li><li><p>创建回归测试：创建一组回归测试，以确保在修复 bug 后不会引入新的 bug。</p></li><li><p>寻求帮助：如果 bug 无法解决，不妨寻求他人的帮助，例如在社区中寻求帮助。</p></li></ol><p>通过运用这些方法，您可以更有效地定位 bug，并加快修复的速度。</p>',20),i=[p];function r(u,n,b,c,s,g){return o(),t("div",null,i)}const d=e(l,[["render",r]]);export{h as __pageData,d as default};
